changeSet.sql:
IF EXISTS (SELECT 1 FROM sys.key_constraints WHERE type = 'PK' AND name = 'PK_CODBI_AI_PROMPT' AND parent_object_id = OBJECT_ID(N'codbi_ai_prompt'))
    ALTER TABLE codbi_ai_prompt DROP CONSTRAINT PK_CODBI_AI_PROMPT;
ALTER TABLE codbi_ai_prompt ALTER COLUMN prompt_key VARCHAR(200) NOT NULL;
IF NOT EXISTS (SELECT 1 FROM sys.key_constraints WHERE type = 'PK' AND name = 'PK_CODBI_AI_PROMPT' AND parent_object_id = OBJECT_ID(N'codbi_ai_prompt'))
    ALTER TABLE codbi_ai_prompt ADD CONSTRAINT PK_CODBI_AI_PROMPT PRIMARY KEY (prompt_key);

